#!/usr/bin/env python3
"""
SIM Instant Share — Windows PC Companion & Local Wi-Fi Hub
----------------------------------------------------------
1. Starts a local Wi-Fi server on your PC (http://<PC-IP>:8765).
2. Any phone on the same Wi-Fi opens that link to scan SIM cards.
3. Scanned numbers arrive instantly on this Windows app (with Auto-Copy to Ctrl+V)
   AND are relayed in real time to any other phone connected to the same Wi-Fi link.

Zero external packages required (uses Python 3 standard library only).
"""

import base64
EMBEDDED_HTML_BYTES = base64.b64decode("")
import csv
import datetime
import json
import os
import socket
import sys
import threading
import urllib.parse
import webbrowser
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

try:
    import tkinter as tk
    from tkinter import filedialog, messagebox, ttk
except ImportError:
    tk = None
    filedialog = messagebox = ttk = None

try:
    import winsound
except ImportError:
    winsound = None

PORT = 8765


def get_resource_path(filename: str) -> str:
    """Resolve path both in normal Python execution and PyInstaller .exe."""
    base_dir = getattr(sys, "_MEIPASS", os.path.dirname(os.path.abspath(__file__)))
    return os.path.join(base_dir, filename)


def get_local_wifi_ip() -> str:
    """Detect the PC's local Wi-Fi/LAN IPv4 address."""
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sock.settimeout(0.5)
        sock.connect(("8.8.8.8", 80))
        ip = sock.getsockname()[0]
        sock.close()
        if ip and not ip.startswith("127."):
            return ip
    except Exception:
        pass
    try:
        ip = socket.gethostbyname(socket.gethostname())
        if ip:
            return ip
    except Exception:
        pass
    return "127.0.0.1"


class SharedStore:
    """Thread-safe store for SIM numbers shared across Wi-Fi."""

    def __init__(self):
        self._lock = threading.Lock()
        self._items = []
        self._seq = 0

    def add(self, payload: dict) -> dict:
        with self._lock:
            self._seq += 1
            entry = {
                "seq": self._seq,
                "id": str(payload.get("id") or f"sim_{self._seq}"),
                "phone": str(payload.get("phone") or payload.get("rawPhone") or ""),
                "rawPhone": str(payload.get("rawPhone") or payload.get("phone") or ""),
                "iccid": str(payload.get("iccid") or ""),
                "pukPin": str(payload.get("pukPin") or ""),
                "senderCode": str(payload.get("senderCode") or ""),
                "timestamp": payload.get("timestamp")
                or int(datetime.datetime.now().timestamp() * 1000),
                "timeStr": datetime.datetime.now().strftime("%H:%M:%S"),
            }
            self._items.insert(0, entry)
            if len(self._items) > 500:
                self._items.pop()
            return entry

    def since(self, seq: int) -> list:
        with self._lock:
            return [x for x in reversed(self._items) if x["seq"] > seq]

    def all_items(self) -> list:
        with self._lock:
            return list(self._items)

    def clear(self):
        with self._lock:
            self._items.clear()


def make_handler(store: SharedStore, html_path: str, on_new_item, local_ip: str):
    class SimShareHandler(BaseHTTPRequestHandler):
        def log_message(self, format, *args):
            return  # Keep console clean

        def _send_json(self, code: int, obj: dict):
            data = json.dumps(obj, ensure_ascii=False).encode("utf-8")
            self.send_response(code)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Access-Control-Allow-Origin", "*")
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(data)

        def do_OPTIONS(self):
            self.send_response(204)
            self.send_header("Access-Control-Allow-Origin", "*")
            self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
            self.send_header("Access-Control-Allow-Headers", "Content-Type")
            self.end_headers()

        def do_GET(self):
            parsed = urllib.parse.urlparse(self.path)
            path = parsed.path

            if path in ("/", "/index.html", "/sim_instant_share.html"):
                content = EMBEDDED_HTML_BYTES
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Content-Length", str(len(content)))
                self.send_header("Cache-Control", "no-store")
                self.end_headers()
                self.wfile.write(content)
                return

            if path == "/api/ping":
                self._send_json(
                    200,
                    {
                        "app": "sim_instant_share_pc",
                        "ok": True,
                        "ip": local_ip,
                        "port": PORT,
                    },
                )
                return

            if path == "/api/list":
                qs = urllib.parse.parse_qs(parsed.query)
                try:
                    since = int(qs.get("since", ["0"])[0])
                except ValueError:
                    since = 0
                self._send_json(200, {"ok": True, "items": store.since(since)})
                return

            self._send_json(404, {"error": "Not found"})

        def do_POST(self):
            parsed = urllib.parse.urlparse(self.path)
            if parsed.path == "/api/send":
                try:
                    length = int(self.headers.get("Content-Length", "0"))
                    raw = self.rfile.read(min(length, 65536))
                    payload = json.loads(raw.decode("utf-8"))
                    entry = store.add(payload)
                    if on_new_item:
                        on_new_item(entry)
                    self._send_json(200, {"ok": True, "item": entry})
                except Exception as exc:
                    self._send_json(400, {"ok": False, "error": str(exc)})
                return

            self._send_json(404, {"error": "Not found"})

    return SimShareHandler


class SimShareDesktopApp:
    def __init__(self, root):
        self.root = root
        self.root.title("SIM Instant Share — Windows Wi-Fi Receiver")
        self.root.geometry("760x580")
        self.root.minsize(640, 480)
        self.root.configure(bg="#f1f5f9")

        self.store = SharedStore()
        self.local_ip = get_local_wifi_ip()
        self.wifi_url = f"http://{self.local_ip}:{PORT}"
        self.html_path = get_resource_path("sim_instant_share.html")
        self.auto_copy_var = tk.BooleanVar(value=True)
        self.sound_var = tk.BooleanVar(value=True)
        self.latest_raw_phone = ""

        self._build_ui()
        self._start_server()

    def _build_ui(self):
        # Top Header Frame
        header = tk.Frame(self.root, bg="#0f172a", padx=18, pady=14)
        header.pack(fill="x")

        title_row = tk.Frame(header, bg="#0f172a")
        title_row.pack(fill="x")

        tk.Label(
            title_row,
            text="SIM Instant Share — نسخة الويندوز (Wi-Fi Hub)",
            font=("Segoe UI", 14, "bold"),
            fg="#ffffff",
            bg="#0f172a",
        ).pack(side="left")

        tk.Label(
            title_row,
            text="● السيرفر شغال (Wi-Fi Active)",
            font=("Segoe UI", 10, "bold"),
            fg="#34d399",
            bg="#0f172a",
        ).pack(side="right")

        # Wi-Fi URL Row
        url_row = tk.Frame(header, bg="#1e293b", padx=12, pady=10)
        url_row.pack(fill="x", pady=(10, 0))

        tk.Label(
            url_row,
            text="افتح هذا الرابط في متصفح الهاتف (نفس الويفي):",
            font=("Segoe UI", 9),
            fg="#cbd5e1",
            bg="#1e293b",
        ).pack(anchor="w")

        link_bar = tk.Frame(url_row, bg="#1e293b")
        link_bar.pack(fill="x", pady=(4, 0))

        self.url_entry = tk.Entry(
            link_bar,
            font=("Consolas", 13, "bold"),
            fg="#fb923c",
            bg="#0f172a",
            relief="flat",
            readonlybackground="#0f172a",
        )
        self.url_entry.insert(0, self.wifi_url)
        self.url_entry.configure(state="readonly")
        self.url_entry.pack(side="left", fill="x", expand=True, ipady=5, padx=(0, 8))

        tk.Button(
            link_bar,
            text="نسخ الرابط",
            command=self._copy_url,
            bg="#f97316",
            fg="#ffffff",
            activebackground="#ea580c",
            relief="flat",
            font=("Segoe UI", 9, "bold"),
            padx=12,
            pady=5,
            cursor="hand2",
        ).pack(side="left", padx=(0, 6))

        tk.Button(
            link_bar,
            text="فتح في المتصفح",
            command=lambda: webbrowser.open(self.wifi_url),
            bg="#334155",
            fg="#ffffff",
            activebackground="#475569",
            relief="flat",
            font=("Segoe UI", 9, "bold"),
            padx=12,
            pady=5,
            cursor="hand2",
        ).pack(side="left")

        # Latest Received Banner
        latest_card = tk.Frame(
            self.root, bg="#ffffff", padx=16, pady=12, highlightbackground="#cbd5e1", highlightthickness=1
        )
        latest_card.pack(fill="x", padx=16, pady=(14, 8))

        top_latest = tk.Frame(latest_card, bg="#ffffff")
        top_latest.pack(fill="x")

        tk.Label(
            top_latest,
            text="آخر رقم SIM وصل عبر الويفي:",
            font=("Segoe UI", 10, "bold"),
            fg="#475569",
            bg="#ffffff",
        ).pack(side="left")

        tk.Checkbutton(
            top_latest,
            text="صوت التنبيه",
            variable=self.sound_var,
            bg="#ffffff",
            font=("Segoe UI", 9),
        ).pack(side="right", padx=(8, 0))

        tk.Checkbutton(
            top_latest,
            text="نسخ تلقائي للـ Clipboard (Ctrl+V)",
            variable=self.auto_copy_var,
            bg="#ffffff",
            fg="#059669",
            font=("Segoe UI", 9, "bold"),
        ).pack(side="right")

        num_row = tk.Frame(latest_card, bg="#ffffff")
        num_row.pack(fill="x", pady=(8, 0))

        self.latest_label = tk.Label(
            num_row,
            text="في انتظار أول بطاقة SIM...",
            font=("Consolas", 22, "bold"),
            fg="#0f172a",
            bg="#f8fafc",
            padx=14,
            pady=8,
            anchor="w",
        )
        self.latest_label.pack(side="left", fill="x", expand=True, padx=(0, 10))

        tk.Button(
            num_row,
            text="نسخ الرقم (Copy)",
            command=self._copy_latest,
            bg="#10b981",
            fg="#ffffff",
            activebackground="#059669",
            relief="flat",
            font=("Segoe UI", 10, "bold"),
            padx=16,
            pady=10,
            cursor="hand2",
        ).pack(side="right")

        # Table Frame
        table_wrap = tk.Frame(self.root, bg="#f1f5f9", padx=16, pady=4)
        table_wrap.pack(fill="both", expand=True)

        columns = ("time", "phone", "iccid", "puk")
        self.tree = ttk.Treeview(table_wrap, columns=columns, show="headings", height=11)
        self.tree.heading("time", text="الوقت")
        self.tree.heading("phone", text="رقم الهاتف (MSISDN)")
        self.tree.heading("iccid", text="ICCID")
        self.tree.heading("puk", text="PUK / PIN")

        self.tree.column("time", width=85, anchor="center")
        self.tree.column("phone", width=180, anchor="center")
        self.tree.column("iccid", width=230, anchor="center")
        self.tree.column("puk", width=170, anchor="center")

        scrollbar = ttk.Scrollbar(table_wrap, orient="vertical", command=self.tree.yview)
        self.tree.configure(yscrollcommand=scrollbar.set)
        self.tree.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")

        self.tree.bind("<Double-1>", lambda _e: self._copy_selected())

        # Bottom Actions Bar
        bottom = tk.Frame(self.root, bg="#f1f5f9", padx=16, pady=12)
        bottom.pack(fill="x")

        tk.Button(
            bottom,
            text="نسخ الرقم المحدد",
            command=self._copy_selected,
            bg="#0f172a",
            fg="#ffffff",
            relief="flat",
            font=("Segoe UI", 9, "bold"),
            padx=12,
            pady=7,
            cursor="hand2",
        ).pack(side="left", padx=(0, 6))

        tk.Button(
            bottom,
            text="نسخ جميع الأرقام",
            command=self._copy_all,
            bg="#ffffff",
            fg="#0f172a",
            relief="solid",
            bd=1,
            font=("Segoe UI", 9, "bold"),
            padx=12,
            pady=6,
            cursor="hand2",
        ).pack(side="left", padx=(0, 6))

        tk.Button(
            bottom,
            text="تصدير CSV (Excel)",
            command=self._export_csv,
            bg="#ffffff",
            fg="#047857",
            relief="solid",
            bd=1,
            font=("Segoe UI", 9, "bold"),
            padx=12,
            pady=6,
            cursor="hand2",
        ).pack(side="left", padx=(0, 6))

        tk.Button(
            bottom,
            text="مسح القائمة",
            command=self._clear_all,
            bg="#fee2e2",
            fg="#b91c1c",
            relief="flat",
            font=("Segoe UI", 9, "bold"),
            padx=12,
            pady=7,
            cursor="hand2",
        ).pack(side="right")

        self.status_var = tk.StringVar(
            value="جاهز! افتح الرابط أعلاه في تليفونك (بنفس الويفي) وصوّر بطاقة SIM."
        )
        tk.Label(
            self.root,
            textvariable=self.status_var,
            bg="#e2e8f0",
            fg="#334155",
            font=("Segoe UI", 9),
            anchor="w",
            padx=14,
            pady=6,
        ).pack(fill="x")

    def _start_server(self):
        handler = make_handler(
            self.store,
            self.html_path,
            lambda entry: self.root.after(0, self._on_new_item, entry),
            self.local_ip,
        )
        try:
            self.httpd = ThreadingHTTPServer(("0.0.0.0", PORT), handler)
            t = threading.Thread(target=self.httpd.serve_forever, daemon=True)
            t.start()
        except OSError as exc:
            messagebox.showerror(
                "Port Error",
                f"تعذر تشغيل السيرفر على المنفذ {PORT}:\n{exc}",
            )

    def _set_clipboard(self, text: str):
        self.root.clipboard_clear()
        self.root.clipboard_append(text)
        self.root.update_idletasks()

    def _on_new_item(self, entry: dict):
        self.latest_raw_phone = entry["rawPhone"] or entry["phone"]
        self.latest_label.configure(text=entry["phone"], fg="#059669")
        self.tree.insert(
            "",
            0,
            values=(entry["timeStr"], entry["phone"], entry["iccid"], entry["pukPin"]),
        )
        if self.auto_copy_var.get() and self.latest_raw_phone:
            self._set_clipboard(self.latest_raw_phone)
            self.status_var.set(f"وصل الرقم {entry['phone']} وتم نسخه تلقائياً (Ctrl+V جاهز)!")
        else:
            self.status_var.set(f"وصل رقم جديد: {entry['phone']}")

        if self.sound_var.get() and winsound:
            try:
                winsound.MessageBeep(winsound.MB_ICONASTERISK)
            except Exception:
                pass

    def _copy_url(self):
        self._set_clipboard(self.wifi_url)
        self.status_var.set(f"تم نسخ رابط الويفي: {self.wifi_url}")

    def _copy_latest(self):
        if not self.latest_raw_phone:
            return
        self._set_clipboard(self.latest_raw_phone)
        self.status_var.set(f"تم نسخ الرقم: {self.latest_raw_phone}")

    def _copy_selected(self):
        sel = self.tree.selection()
        if not sel:
            return
        vals = self.tree.item(sel[0], "values")
        if vals and len(vals) >= 2:
            raw = "".join(ch for ch in str(vals[1]) if ch.isdigit()) or str(vals[1])
            self._set_clipboard(raw)
            self.status_var.set(f"تم نسخ الرقم: {raw}")

    def _copy_all(self):
        items = self.store.all_items()
        if not items:
            return
        lines = "\n".join(x["rawPhone"] or x["phone"] for x in items)
        self._set_clipboard(lines)
        self.status_var.set(f"تم نسخ {len(items)} رقم إلى الحافظة!")

    def _export_csv(self):
        items = self.store.all_items()
        if not items:
            return
        path = filedialog.asksaveasfilename(
            defaultextension=".csv",
            filetypes=[("CSV files", "*.csv")],
            initialfile=f"sim_numbers_{datetime.date.today().isoformat()}.csv",
        )
        if not path:
            return
        with open(path, "w", newline="", encoding="utf-8-sig") as f:
            writer = csv.writer(f)
            writer.writerow(["Time", "Phone", "ICCID", "PUK_PIN"])
            for x in items:
                writer.writerow([x["timeStr"], x["rawPhone"] or x["phone"], x["iccid"], x["pukPin"]])
        self.status_var.set(f"تم حفظ ملف CSV بنجاح: {os.path.basename(path)}")

    def _clear_all(self):
        self.store.clear()
        for row in self.tree.get_children():
            self.tree.delete(row)
        self.latest_raw_phone = ""
        self.latest_label.configure(text="في انتظار أول بطاقة SIM...", fg="#0f172a")
        self.status_var.set("تم مسح القائمة.")


def main():
    if tk is None:
        print("Tkinter is required for the desktop GUI.")
        sys.exit(1)
    root = tk.Tk()
    app = SimShareDesktopApp(root)
    root.mainloop()


if __name__ == "__main__":
    main()
